function qs(selector) {
  return document.querySelector(selector);
}

function qsa(selector) {
  return Array.from(document.querySelectorAll(selector));
}

function escapeHtml(value) {
  return String(value)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

function formatCr(value) {
  return `Rs. ${Number(value).toLocaleString("en-IN")} cr`;
}

function formatMoney(value) {
  const amount = Number(value);
  if (amount >= 10000000) return `Rs. ${(amount / 10000000).toFixed(2)} cr`;
  if (amount >= 100000) return `Rs. ${(amount / 100000).toFixed(2)} lakh`;
  return `Rs. ${Math.round(amount).toLocaleString("en-IN")}`;
}

function nadiScore(fund) {
  const drawdownControl = Math.max(0, 100 - fund.maxDrawdown * 2.1);
  const expenseScore = Math.max(0, 100 - fund.expense * 75);
  return Math.round(
    fund.consistency * 0.34 +
    drawdownControl * 0.22 +
    expenseScore * 0.18 +
    fund.researchCoverage * 0.16 +
    Math.min(fund.returns5y * 3.4, 100) * 0.1
  );
}

function nadiScoreParts(fund) {
  const drawdownControl = Math.max(0, 100 - fund.maxDrawdown * 2.1);
  const expenseScore = Math.max(0, 100 - fund.expense * 75);
  const returnSupport = Math.min(fund.returns5y * 3.4, 100);
  const parts = [
    {
      id: "consistency",
      label: "Consistency",
      raw: fund.consistency,
      weight: 34,
      contribution: fund.consistency * 0.34,
      detail: "Rewards smoother category-relative behavior and repeatability in demo data.",
      improve: "Improve only with steadier rolling performance and fewer style surprises."
    },
    {
      id: "drawdown",
      label: "Drawdown control",
      raw: drawdownControl,
      weight: 22,
      contribution: drawdownControl * 0.22,
      detail: `${fund.maxDrawdown}% demo drawdown is translated into a control score.`,
      improve: "Improves when downside capture, volatility, and peak-to-trough falls are lower."
    },
    {
      id: "expense",
      label: "Expense discipline",
      raw: expenseScore,
      weight: 18,
      contribution: expenseScore * 0.18,
      detail: `${fund.expense.toFixed(2)}% TER is converted into a cost discipline score.`,
      improve: "Improves when TER is lower or stays below category and sleeve peers."
    },
    {
      id: "coverage",
      label: "Research coverage",
      raw: fund.researchCoverage,
      weight: 16,
      contribution: fund.researchCoverage * 0.16,
      detail: "Rewards available demo research coverage for style, role, holdings, and manager context.",
      improve: "Improves when source-backed factsheet, SID/KIM, portfolio, TER, and riskometer fields are richer."
    },
    {
      id: "return",
      label: "Return support",
      raw: returnSupport,
      weight: 10,
      contribution: returnSupport * 0.1,
      detail: `${fund.returns5y.toFixed(1)}% five-year demo return is capped so returns never dominate the score.`,
      improve: "Improves with persistent category-relative returns, but remains capped to avoid performance chasing."
    }
  ];
  const score = Math.round(parts.reduce((sum, part) => sum + part.contribution, 0));
  return { drawdownControl, expenseScore, parts, returnSupport, score };
}

function scoreAnatomyBand(score) {
  if (score >= 82) return "Strong demo score";
  if (score >= 72) return "Research-worthy score";
  if (score >= 62) return "Needs stronger proof";
  return "Watch before shortlisting";
}

function scoreAnatomyConfig() {
  const fund = selectedFund();
  const anatomy = nadiScoreParts(fund);
  const peer = peerBenchmarkConfig();
  const evidence = evidenceReadinessScore(fund);
  const weakest = [...anatomy.parts].sort((a, b) => a.raw - b.raw)[0];
  const strongest = [...anatomy.parts].sort((a, b) => b.raw - a.raw)[0];
  const peerDelta = anatomy.score - peer.sleeveAvg.score;
  const notes = [
    `The Nadi score is a weighted research score, not a rating, recommendation, or guarantee.`,
    `Largest driver: ${strongest.label} contributes ${strongest.contribution.toFixed(1)} points.`,
    `Weakest driver: ${weakest.label} has a raw score of ${Math.round(weakest.raw)}/100.`,
    evidence < 70
      ? `Evidence readiness is ${evidence}/100, so source proof is the first trust gate even if the score looks usable.`
      : `Evidence readiness is ${evidence}/100, but live source dates and citations are still required before launch use.`
  ];
  const pressure = [];
  if (fund.maxDrawdown >= 18) pressure.push("Drawdown control is under pressure; run Stress Lab before any memo.");
  if (fund.expense > peer.sleeveAvg.expense + 0.12) pressure.push("Expense discipline is under pressure versus sleeve peers.");
  if (fund.researchCoverage < 78 || evidence < 78) pressure.push("Coverage and citation depth should be strengthened before relying on the score.");
  if (fund.returns5y * 3.4 >= 100) pressure.push("Return support is capped, so recent performance cannot overpower risk and cost.");
  if (!pressure.length) pressure.push("No single score driver dominates; still verify peer context and live evidence.");

  return {
    anatomy,
    evidence,
    fund,
    notes,
    peer,
    peerDelta,
    pressure,
    score: anatomy.score,
    status: scoreAnatomyBand(anatomy.score),
    strongest,
    weakest
  };
}

function signalStripConfig() {
  const fund = selectedFund();
  const score = nadiScore(fund);
  const evidence = evidenceReadinessScore(fund);
  const peer = peerBenchmarkConfig();
  const compareFunds = compareSet();
  const riskControl = Math.round(Math.max(0, 100 - fund.maxDrawdown * 2));
  const sleeveDelta = score - peer.sleeveAvg.score;
  const stressRequired = fund.maxDrawdown >= 22 || fund.risk === "Very High";
  const costNeedsCheck = fund.expense > peer.sleeveAvg.expense + 0.1;

  let posture = "Research candidate";
  let tone = "steady";
  let postureCopy = "Score, cost, and evidence are usable for deeper self-research.";
  if (evidence < 70) {
    posture = "Evidence first";
    tone = "caution";
    postureCopy = "Score is secondary until source dates, citations, and demo/live status are checked.";
  } else if (stressRequired) {
    posture = "Stress test first";
    tone = "watch";
    postureCopy = "Drawdown behavior should be understood before any SIP or switch memo.";
  } else if (score >= 80 && sleeveDelta >= 0) {
    posture = "Strong shortlist";
    tone = "ready";
    postureCopy = "This fund is ahead of its sleeve peer signal, but still needs evidence and role checks.";
  } else if (costNeedsCheck) {
    posture = "Cost check";
    tone = "watch";
    postureCopy = "TER is above the sleeve comfort line, so rupee cost impact should be reviewed.";
  }

  let next = {
    label: "Compare role",
    route: "#compare",
    reason: "Add at least one peer before deciding whether this fund has a distinct job."
  };
  if (evidence < 78) {
    next = {
      label: "Open Evidence",
      route: "#evidence",
      reason: "Confirm AMFI, AMC factsheet, SID/KIM, TER, portfolio, and riskometer readiness."
    };
  } else if (stressRequired) {
    next = {
      label: "Run Stress",
      route: "#risk-lab",
      reason: "Convert drawdown into rupee impact before writing a decision reason."
    };
  } else if (costNeedsCheck) {
    next = {
      label: "Check Cost",
      route: "#cost-lab",
      reason: "Compare TER drag, tax friction, and lower-cost alternatives."
    };
  } else if (compareFunds.length >= 2) {
    next = {
      label: "Build Pack",
      route: "#decision-pack",
      reason: "The shortlist is ready for a written memo with amount, review date, and guardrails."
    };
  }

  const quickRoutes = [
    { label: "Mission", route: "#autopilotMissionPlan" },
    { label: "Score", route: "#score-anatomy" },
    { label: "Evidence", route: "#evidence" },
    { label: "Stress", route: "#risk-lab" },
    { label: "Pack", route: "#decision-pack" }
  ];

  return {
    compareCount: compareFunds.length,
    costNeedsCheck,
    evidence,
    fund,
    next,
    peer,
    posture,
    postureCopy,
    quickRoutes,
    riskControl,
    score,
    sleeveDelta,
    stressRequired,
    tone
  };
}

function simpleStepHashFromRoute(hash = "") {
  return SIMPLE_ROUTE_STEP_BY_HASH.get(hash) || "";
}

function simpleJourneyConfig(signal = signalStripConfig(), activeHash = window.location.hash || "") {
  const suggestedRoute = simpleStepHashFromRoute(signal.next.route) || "#screener";
  const viewedRoute = simpleStepHashFromRoute(activeHash);
  const activeRoute = viewedRoute || suggestedRoute;
  const activeStepIndex = Math.max(0, SIMPLE_JOURNEY_STEPS.findIndex((step) => step.value === activeRoute));
  const activeStep = SIMPLE_JOURNEY_STEPS[activeStepIndex] || SIMPLE_JOURNEY_STEPS[1];
  const question = simpleJourneyQuestion(activeStep, signal);
  return {
    activeStep,
    activeStepIndex,
    next: signal.next,
    question,
    steps: SIMPLE_JOURNEY_STEPS,
    summary: viewedRoute && viewedRoute !== suggestedRoute
      ? `You are here in ${activeStep.label}. Suggested next move: ${signal.next.label}.`
      : `${signal.next.label}: ${signal.next.reason}`
  };
}

function simpleJourneyQuestion(step, signal) {
  const questionMap = {
    "#profile-room": {
      label: "Is the investor context written?",
      detail: "Confirm goal, horizon, SIP comfort, emergency buffer, and drawdown comfort before comparing funds."
    },
    "#screener": {
      label: signal.compareCount >= 2 ? "Does this fund have a distinct job?" : "Which peer will you compare?",
      detail: signal.compareCount >= 2
        ? "Use role, cost, drawdown, and evidence to decide whether this fund deserves shortlist space."
        : "Add at least one peer so the fund is not judged in isolation."
    },
    "#evidence": {
      label: signal.evidence >= 78 ? "Can the source be cited?" : "Which source date is missing?",
      detail: signal.evidence >= 78
        ? "Carry the source date, citation path, and demo/live status into the memo."
        : "Check AMFI, AMC factsheet, SID/KIM, TER, portfolio, benchmark, and riskometer readiness."
    },
    "#decision-pack": {
      label: "Can the reason survive tomorrow?",
      detail: "Write why this fund, why this amount, what review date, and what would make you pause."
    },
    "#review-vault": {
      label: "What will trigger the next review?",
      detail: "Save the review date, score drift, expense change, drawdown trigger, or evidence refresh reminder."
    }
  };
  return questionMap[step.value] || questionMap["#screener"];
}

function simpleProgressMemory(activeStep) {
  const validRoutes = new Set(SIMPLE_JOURNEY_STEPS.map((step) => step.value));
  let visited = [];
  try {
    const saved = JSON.parse(localStorage.getItem(SIMPLE_PROGRESS_KEY) || "[]");
    if (Array.isArray(saved)) {
      visited = [...new Set(saved.filter((route) => validRoutes.has(route)))];
    }
  } catch (error) {
    visited = [];
  }

  if (!simpleSessionResumeRoute) {
    try {
      const lastRoom = localStorage.getItem(SIMPLE_LAST_ROOM_KEY) || "";
      if (validRoutes.has(lastRoom)) {
        simpleSessionResumeRoute = lastRoom;
      }
    } catch (error) {
      simpleSessionResumeRoute = "";
    }
  }

  if (activeStep?.value && validRoutes.has(activeStep.value) && !visited.includes(activeStep.value)) {
    visited.push(activeStep.value);
  }

  if (activeStep?.value && validRoutes.has(activeStep.value)) {
    try {
      localStorage.setItem(SIMPLE_PROGRESS_KEY, JSON.stringify(visited));
      localStorage.setItem(SIMPLE_LAST_ROOM_KEY, activeStep.value);
    } catch (error) {
      // Progress memory is only a browser-local comfort layer.
    }
  }

  const visitedSet = new Set(visited);
  const visitedCount = visitedSet.size;
  const activeIndex = Math.max(0, SIMPLE_JOURNEY_STEPS.findIndex((step) => step.value === activeStep?.value));
  const nextUntouched = SIMPLE_JOURNEY_STEPS.find((step, index) => index > activeIndex && !visitedSet.has(step.value))
    || SIMPLE_JOURNEY_STEPS.find((step) => !visitedSet.has(step.value));
  const resumeStep = SIMPLE_JOURNEY_STEPS.find((step) => step.value === simpleSessionResumeRoute && step.value !== activeStep?.value) || null;
  const isComplete = visitedCount >= SIMPLE_JOURNEY_STEPS.length;
  const finishStep = SIMPLE_JOURNEY_STEPS.find((step) => step.value === "#review-vault")
    || SIMPLE_JOURNEY_STEPS[SIMPLE_JOURNEY_STEPS.length - 1];
  return {
    activePosition: isComplete ? "Research round" : `Step ${activeStep?.number || "02"} of ${String(SIMPLE_JOURNEY_STEPS.length).padStart(2, "0")}`,
    label: `${visitedCount}/${SIMPLE_JOURNEY_STEPS.length} rooms touched`,
    nextMemory: isComplete ? "Complete: save review" : nextUntouched ? `Next untouched: ${nextUntouched.label}` : "All five rooms touched",
    resumeStep,
    finishStep: isComplete ? finishStep : null,
    isComplete,
    canReset: visitedCount > 1 || Boolean(resumeStep),
    visitedSet
  };
}

function clearSimpleProgressMemory() {
  simpleSessionResumeRoute = "";
  try {
    localStorage.removeItem(SIMPLE_PROGRESS_KEY);
    localStorage.removeItem(SIMPLE_LAST_ROOM_KEY);
  } catch (error) {
    // The reset is only a browser-local comfort layer.
  }
}

function resetSimpleProgressMemory() {
  clearSimpleProgressMemory();
  renderSimplicityPath(signalStripConfig(), window.location.hash || workspaceHashFromViewport());
}

function startNextResearchRound() {
  clearSimpleProgressMemory();
  scrollToHash("#profile-room", "smooth", true);
  renderSimplicityPath(signalStripConfig(), "#profile-room");
  renderReviewVault();
  toast("Next research round started. Saved reviews are kept.");
}

function investorTakeaway(signal) {
  if (signal.evidence < 78) {
    return "Do not treat this as ready yet. Verify source dates first, then decide whether the fund deserves shortlist space.";
  }
  if (signal.stressRequired) {
    return "This can be researched, but the next real question is whether the drawdown feels acceptable in rupee terms.";
  }
  if (signal.costNeedsCheck) {
    return "This may fit the role, but cost needs a quick rupee check before it earns a memo.";
  }
  if (signal.compareCount < 2) {
    return "Add one peer before judging it. A fund only becomes clear when its job is compared.";
  }
  return "This is ready for a written research memo: role, amount, review date, and stop-checks.";
}

function decisionReadiness(signal) {
  const memoReady = signal.evidence >= 78 && signal.compareCount >= 2 && !signal.stressRequired && !signal.costNeedsCheck;
  const checks = [
    {
      label: "Evidence",
      state: signal.evidence >= 78 ? "Ready" : "Blocked",
      detail: signal.evidence >= 78 ? "Source path can be carried into memo." : "Verify source dates first."
    },
    {
      label: "Peer",
      state: signal.compareCount >= 2 ? "Ready" : "Needed",
      detail: signal.compareCount >= 2 ? "At least one comparison is present." : "Add one peer before judging."
    },
    {
      label: "Memo",
      state: memoReady ? "Ready" : "Not yet",
      detail: memoReady ? "Write role, amount, review date, and stop-checks." : "Clear the next check before memo."
    }
  ];
  const readyCount = checks.filter((check) => check.state === "Ready").length;
  const status = readyCount === checks.length ? "Memo-ready" : readyCount >= 2 ? "Almost ready" : "Blocked";
  return { checks, readyCount, status };
}

function doNextCue(signal, readiness) {
  const blocker = readiness.checks.find((check) => check.state !== "Ready");
  if (!blocker) {
    return {
      label: "Do next",
      title: "Write the decision memo",
      detail: "Capture role, amount, review date, and stop-checks before any real action.",
      route: "#decision-pack",
      button: "Build Pack",
      tone: "ready"
    };
  }
  if (blocker.label === "Evidence") {
    return {
      label: "Do next",
      title: "Verify evidence first",
      detail: "Do not judge the fund until source dates and citation paths are clear.",
      route: "#evidence",
      button: "Open Evidence",
      tone: "caution"
    };
  }
  if (blocker.label === "Peer") {
    return {
      label: "Do next",
      title: "Add one fair peer",
      detail: "Compare role, cost, drawdown, and evidence before deciding shortlist space.",
      route: "#compare",
      button: "Compare Role",
      tone: "watch"
    };
  }
  return {
    label: "Do next",
    title: signal.next.label,
    detail: signal.next.reason,
    route: signal.next.route,
    button: signal.next.label,
    tone: signal.tone
  };
}

function threeStepPlan(signal, readiness, nextCue) {
  const stepOne = {
    label: "01 Now",
    title: nextCue.title,
    detail: nextCue.detail,
    route: nextCue.route,
    state: "active"
  };
  const evidenceStep = {
    label: "02 Then",
    title: "Lock source proof",
    detail: "Make sure factsheet, TER, holdings, and riskometer dates can be cited.",
    route: "#evidence",
    state: readiness.checks[0]?.state === "Ready" ? "ready" : "queued"
  };
  const compareStep = {
    label: "02 Then",
    title: "Compare one peer",
    detail: "Check role, cost, drawdown, and evidence against a fair alternative.",
    route: "#compare",
    state: signal.compareCount >= 2 ? "ready" : "queued"
  };
  const stressStep = {
    label: "02 Then",
    title: "Feel the rupee risk",
    detail: "Turn drawdown into money terms before increasing SIP or switching.",
    route: "#risk-lab",
    state: "queued"
  };
  const costStep = {
    label: "02 Then",
    title: "Check cost drag",
    detail: "Review TER and lower-cost alternatives before writing a memo.",
    route: "#cost-lab",
    state: "queued"
  };
  const memoStep = {
    label: "03 Final",
    title: "Write memo",
    detail: "Record reason, amount, review date, and stop-checks before any real action.",
    route: "#decision-pack",
    state: "queued"
  };
  const reviewStep = {
    label: "03 Final",
    title: "Set review rhythm",
    detail: "Save the review date or trigger so the decision is not forgotten.",
    route: "#review-vault",
    state: "queued"
  };
  const journalStep = {
    label: "02 Then",
    title: "Save the reason",
    detail: "Put the decision reason in writing before the review rhythm starts.",
    route: "#journal",
    state: "queued"
  };

  let second = compareStep;
  if (nextCue.route === "#compare") second = evidenceStep;
  if (nextCue.route === "#risk-lab") second = costStep;
  if (nextCue.route === "#cost-lab") second = stressStep;
  if (nextCue.route === "#decision-pack") second = journalStep;

  return [stepOne, second, nextCue.route === "#decision-pack" ? reviewStep : memoStep];
}

function renderSimplicityPath(signal = signalStripConfig(), activeHash = window.location.hash || workspaceHashFromViewport()) {
  if (!els.simplicityPath) return;
  const journey = simpleJourneyConfig(signal, activeHash);
  const progress = simpleProgressMemory(journey.activeStep);
  const readiness = decisionReadiness(signal);
  const nextCue = doNextCue(signal, readiness);
  const quietRail = quietDecisionRail(signal, readiness, journey);
  renderHeaderNextAction(journey);
  renderSerenityStartSurface(signal, journey, readiness, nextCue);
  renderSimpleRoomCue(journey, progress);
  els.simplicityPath.classList.add("serenity-path");
  els.simplicityPath.innerHTML = `
    <div class="simplicity-path-copy">
      <span>Today's quiet path</span>
      <strong>Step ${escapeHtml(journey.activeStep.number)}: ${escapeHtml(journey.activeStep.label)}</strong>
      <p>${escapeHtml(journey.summary)}</p>
      <div class="serenity-checkline" aria-label="Calm decision posture">
        <span>Research only</span>
        <span>Evidence first</span>
        <span>No rush</span>
      </div>
      ${progress.resumeStep ? `
        <button class="signal-chip simplicity-resume" type="button" data-signal-route="${escapeHtml(progress.resumeStep.value)}" aria-label="Resume last room: ${escapeHtml(progress.resumeStep.label)}">
          <span>Resume</span>
          <strong>${escapeHtml(progress.resumeStep.label)}</strong>
        </button>
      ` : ""}
    </div>
    <div class="simplicity-question">
      <span>Only question now</span>
      <strong>${escapeHtml(journey.question.label)}</strong>
      <p>${escapeHtml(journey.question.detail)}</p>
    </div>
    <div class="quiet-decision-rail quiet-decision-rail--simple" aria-label="Quiet decision rail">
      <div class="quiet-decision-rail-copy">
        <span>${escapeHtml(quietRail.label)}</span>
        <strong>${escapeHtml(quietRail.headline)}</strong>
        <small>${escapeHtml(quietRail.cue)}</small>
      </div>
      <ol class="quiet-decision-steps">
        ${quietRail.steps.map((step) => `
          <li class="${step.ready ? "is-done" : "is-waiting"}">
            <span>${escapeHtml(step.label)}</span>
            <strong>${escapeHtml(step.title)}</strong>
            <small>${escapeHtml(step.detail)}</small>
          </li>
        `).join("")}
      </ol>
      <div class="quiet-decision-now">
        <span>Next calm check</span>
        <strong>${escapeHtml(quietRail.nextTitle)}</strong>
        <small>${escapeHtml(quietRail.nextDetail)}</small>
      </div>
    </div>
    <button class="text-button simplicity-next primary-next-action calm-next-action" type="button" data-signal-route="${escapeHtml(journey.next.route)}" aria-label="Open next action: ${escapeHtml(journey.next.label)}">
      <span>Next calm step</span>
      <strong>${escapeHtml(journey.next.label)}</strong>
      <em>${escapeHtml(journey.next.reason)}</em>
    </button>
    <div class="simplicity-path-actions">
      ${journey.steps.map((step, index) => {
        const stateClass = index < journey.activeStepIndex ? " is-done" : index === journey.activeStepIndex ? " is-active" : "";
        const memoryClass = progress.visitedSet.has(step.value) ? " is-visited" : "";
        const current = index === journey.activeStepIndex ? ' aria-current="step"' : "";
        const marker = index === journey.activeStepIndex ? '<em class="step-focus-marker">Current</em>' : "";
        return `<button class="signal-chip simple-step${stateClass}${memoryClass}" type="button" data-signal-route="${escapeHtml(step.value)}"${current}><span>${escapeHtml(step.number)}</span><strong>${escapeHtml(step.label)}</strong>${marker}</button>`;
      }).join("")}
    </div>
  `;
}

function quietConvictionMeter(readiness) {
  const steps = (readiness.checks || []).map((check) => ({
    label: check.label,
    ready: check.state === "Ready"
  }));
  const readyCount = steps.filter((step) => step.ready).length;
  if (readiness.status === "Memo-ready") {
    return {
      label: "Quiet conviction",
      state: "Memo-ready",
      text: "Enough checks are visible for a written memo, not execution.",
      cue: "Write the reason before any action.",
      steps
    };
  }
  if (readyCount >= 2) {
    return {
      label: "Quiet conviction",
      state: "Research warming",
      text: "A few checks are visible, but one blocker still deserves patience.",
      cue: "Clear the next check before conviction rises.",
      steps
    };
  }
  return {
    label: "Quiet conviction",
    state: "Still research",
    text: "Conviction stays low until evidence, peer, and memo checks are visible.",
    cue: "Let the desk stay quiet before the investor gets confident.",
    steps
  };
}

function learningLoopLedger(signal, readiness) {
  const checks = readiness.checks || [];
  const readyCount = checks.filter((check) => check.state === "Ready").length;
  const memoReady = readiness.status === "Memo-ready";
  const posture = memoReady
    ? "Learning loop ready"
    : readyCount >= 2
      ? "Learning loop warming"
      : "Learning loop observing";
  const headline = memoReady
    ? "A reviewed memo can teach the next route."
    : "Observe, verify, write, review before the desk learns from this action.";
  return {
    label: "Closed-loop learning",
    posture,
    headline,
    receipt: ["NN", "LEARNING", "LOOP", DATA_VERSION.replace(/-/g, ""), signal.fund.id].join("-").toUpperCase(),
    loops: [
      { label: "Action signal", state: "Captured" },
      { label: "Outcome memory", state: memoReady ? "Ready" : "Waiting" },
      { label: "Privacy filter", state: "On" }
    ],
    safeguards: ["Anonymous patterns only", "Human review before release", "No personal IDs"]
  };
}

function federatedTrustLoop(signal, readiness) {
  const checks = readiness.checks || [];
  const readyCount = checks.filter((check) => check.state === "Ready").length;
  const evidenceReady = signal.evidence >= 78;
  const posture = readyCount >= 3 && evidenceReady
    ? "Pattern share ready"
    : readyCount >= 2
      ? "Local learning only"
      : "Observe before learning";
  return {
    label: "Federated trust loop",
    posture,
    headline: "Local actions improve this desk; only anonymous patterns can help other organizations.",
    receipt: ["NN", "FEDERATED", "TRUST", DATA_VERSION.replace(/-/g, ""), signal.fund.id].join("-").toUpperCase(),
    cells: [
      { label: "Local loop", state: "Learns here" },
      { label: "Shared pattern", state: evidenceReady ? "Allowed later" : "Blocked" },
      { label: "Privacy wall", state: "Always on" }
    ],
    guardrails: ["No raw notes shared", "No investor identity", "Review before release"]
  };
}

function learningConsentGate(signal, readiness) {
  const memoReady = readiness.status === "Memo-ready";
  const evidenceReady = signal.evidence >= 78;
  const posture = memoReady && evidenceReady ? "Consent gate ready" : "Consent required";
  return {
    label: "Learning consent gate",
    posture,
    headline: "Learning is useful only after consent, anonymization, and review are clear.",
    receipt: ["NN", "LEARNING", "CONSENT", DATA_VERSION.replace(/-/g, ""), signal.fund.id].join("-").toUpperCase(),
    checks: [
      { label: "Consent", state: "Required" },
      { label: "Anonymized", state: "Pattern only" },
      { label: "Reviewer", state: memoReady ? "Ready" : "Before release" }
    ],
    promise: "No cross-organization learning without consent.",
    safeguards: ["Org-local first", "Anonymous aggregate only", "Opt-out by design"]
  };
}

function outcomeLearningSignal(signal, readiness) {
  const memoReady = readiness.status === "Memo-ready";
  const reviewReady = signal.evidence >= 78 && signal.compareCount >= 2 && memoReady;
  const posture = reviewReady ? "Lesson can be reviewed" : "Outcome waiting";
  return {
    label: "Outcome learning signal",
    posture,
    headline: "The desk learns only after a decision is saved, reviewed, and turned into an anonymous lesson.",
    receipt: ["NN", "OUTCOME", "LEARNING", DATA_VERSION.replace(/-/g, ""), signal.fund.id].join("-").toUpperCase(),
    cycle: [
      { label: "Decision", state: memoReady ? "Written" : "Not ready" },
      { label: "Review", state: signal.evidence >= 78 ? "Evidence checked" : "Evidence first" },
      { label: "Lesson", state: reviewReady ? "Reviewable" : "Private draft" }
    ],
    reinforcement: "Better prompts, safer gates, and clearer defaults improve from reviewed patterns, not raw notes.",
    safeguards: ["No return prediction", "No raw investor notes", "Org review before sharing"]
  };
}

function privacyLearningLedger(signal, readiness, journey) {
  const memoReady = readiness.status === "Memo-ready";
  const evidenceReady = signal.evidence >= 78;
  const posture = evidenceReady && memoReady ? "Ready to review" : "Private learning draft";
  const roundLabel = journey?.activeStep?.label || "Current route";
  const releaseGate = evidenceReady && memoReady ? "Reviewer can approve" : "Human review pending";
  return {
    label: "Privacy-safe learning ledger",
    posture,
    headline: "Only anonymous patterns can improve the desk.",
    brief: "Organization learning waits for consent.",
    receipt: ["NN", "PRIVACY", "LEARNING", "LEDGER", DATA_VERSION.replace(/-/g, ""), signal.fund.id].join("-").toUpperCase(),
    receiptLabel: "Learning receipt",
    receiptHeadline: "This action teaches the desk only after review.",
    cells: [
      { label: "Can learn", state: "Route patterns" },
      { label: "Must wait", state: memoReady ? "Saved review" : "Written reason" },
      { label: "Never learns", state: "Personal IDs" }
    ],
    receiptRows: [
      { label: "Observed", state: `${roundLabel} pattern` },
      { label: "Shared as", state: "Anonymous signal" },
      { label: "Release gate", state: releaseGate }
    ],
    cue: `${roundLabel}: keep learning local until evidence, memo, and review are ready.`,
    guardrail: "No PAN, folio, CAS, contact, or bank data."
  };
}

function calmReviewCompass(signal, readiness, journey) {
  const roundLabel = journey?.activeStep?.label || "Current route";
  const memoReady = readiness.status === "Memo-ready";
  const evidenceReady = signal.evidence >= 78;
  return {
    label: "Calm review compass",
    posture: "Observe, decide, improve",
    brief: "The desk should learn from a completed research round, not from a rushed click.",
    cards: [
      {
        label: "Observe",
        state: "One fund, one fair peer, one source date.",
        detail: `Capture the ${roundLabel.toLowerCase()} signal without judging it.`
      },
      {
        label: "Decide",
        state: "Keep, watch, or pause only after memo.",
        detail: memoReady ? "The reason exists; keep the review date visible." : "A written reason keeps excitement from becoming action."
      },
      {
        label: "Improve",
        state: "Anonymous patterns can train the desk after review.",
        detail: evidenceReady ? "Learning can wait for consent and release." : "Evidence gaps stay local until source dates are clear."
      }
    ],
    cue: "Closed-loop learning stays useful only when the next action is simple."
  };
}

function learningFlywheelContract(signal, readiness, journey) {
  const roundLabel = journey?.activeStep?.label || "Current route";
  const evidenceReady = signal.evidence >= 78;
  const memoReady = readiness.status === "Memo-ready";
  const releaseReady = evidenceReady && memoReady;
  return {
    label: "Learning flywheel contract",
    posture: releaseReady ? "Ready for reviewed learning" : "Learning stays in draft",
    brief: "Every useful AI loop begins with a tiny human-reviewed action.",
    receipt: ["NN", "CALM", "LEARNING", "CONTRACT", DATA_VERSION.replace(/-/g, ""), signal.fund.id].join("-").toUpperCase(),
    rules: [
      {
        label: "Capture",
        state: "Capture only the research pattern.",
        detail: `${roundLabel}: fund, peer, source gap, memo state, and next check.`
      },
      {
        label: "Review",
        state: "Review before the desk learns.",
        detail: memoReady ? "The memo can be replayed before learning is accepted." : "The memo is still the human gate."
      },
      {
        label: "Improve",
        state: "Improve only with consent.",
        detail: evidenceReady ? "Evidence can support a future pattern after release." : "Source gaps keep the pattern local."
      }
    ],
    guards: [
      "No personal IDs enter the learning loop.",
      "Human review before release.",
      "Cross-organization learning waits for explicit consent."
    ]
  };
}

function calmLearningReceipt(signal, readiness, journey) {
  const roundLabel = journey?.activeStep?.label || "Current route";
  const evidenceReady = signal.evidence >= 78;
  const memoReady = readiness.status === "Memo-ready";
  const reviewable = evidenceReady && memoReady;
  return {
    label: "Calm learning receipt",
    posture: reviewable ? "Reviewable lesson" : "Draft lesson only",
    headline: "The desk learns only from reviewed patterns, never from identity.",
    receipt: ["NN", "CALM", "LEARNING", "RECEIPT", DATA_VERSION.replace(/-/g, ""), signal.fund.id].join("-").toUpperCase(),
    canLearn: [
      { label: "Fund role", state: signal.fund.category },
      { label: "Source gap", state: evidenceReady ? "Evidence visible" : "Evidence first" },
      { label: "Memo state", state: memoReady ? "Written" : "Reason pending" },
      { label: "Review rhythm", state: roundLabel }
    ],
    refuses: [
      "PAN, folio, CAS, contact, or bank data",
      "Raw private notes",
      "Action without human review",
      "Cross-organization learning without consent"
    ],
    strip: [
      { label: "Learning mode", state: "Anonymous pattern" },
      { label: "Release", state: reviewable ? "Reviewer can approve" : "Local draft" },
      { label: "Privacy wall", state: "On" }
    ],
    cue: "Useful reinforcement begins after evidence, memo, review, and consent."
  };
}

function calmImprovementPromise(signal, readiness, journey) {
  const roundLabel = journey?.activeStep?.label || "Current route";
  const evidenceReady = signal.evidence >= 78;
  const memoReady = readiness.status === "Memo-ready";
  const nextBenefit = memoReady
    ? "Clearer review prompts"
    : evidenceReady
      ? "Sharper memo gate"
      : "Quieter first question";
  return {
    label: "Calm improvement promise",
    posture: "Improve the route, not the investor",
    headline: "Every reviewed lesson should make the next screen quieter.",
    cells: [
      { label: "Next user benefit", state: nextBenefit },
      { label: "What improves", state: `${roundLabel} wording and order` },
      { label: "What stays private", state: "No identity, private notes, or unreviewed action." }
    ],
    cue: "The product learns to reduce confusion, not to push behavior."
  };
}

function calmEvidenceBeacon(signal, readiness, journey) {
  const roundLabel = journey?.activeStep?.label || "Current route";
  const evidenceReady = signal.evidence >= 78;
  const sourceState = evidenceReady ? "Current enough to cite" : "Verify source date";
  const citationState = evidenceReady ? "Visible enough" : "Missing or demo";
  const reviewState = readiness.status === "Memo-ready" ? "Memo can review" : `${roundLabel} first`;
  return {
    label: "Source-date beacon",
    posture: "Evidence before confidence",
    headline: "The desk should stay quiet until source dates, citations, TER, holdings, and riskometer checks are visible.",
    cells: [
      { label: "Source date", state: sourceState },
      { label: "Citation path", state: citationState },
      { label: "Review gate", state: reviewState }
    ],
    guards: ["No PAN", "No push", "Review first"],
    cue: "Trust the score only after the source trail is visible."
  };
}

function quietDecisionRail(signal, readiness, journey) {
  const evidenceReady = signal.evidence >= 78;
  const peerReady = signal.compareCount >= 2;
  const memoReady = readiness.status === "Memo-ready";
  const reviewReady = readiness.score >= 70 && memoReady;
  const routeLabel = journey?.activeStep?.label || "Current room";
  const steps = [
    { label: "Name", title: "One fund in focus", detail: signal.fund.name, ready: true },
    {
      label: "Verify",
      title: evidenceReady ? "Source trail visible" : "Source date missing",
      detail: evidenceReady ? "Evidence can be cited." : "Open Evidence before confidence.",
      ready: evidenceReady
    },
    {
      label: "Compare",
      title: peerReady ? "Fair peer visible" : "Add one fair peer",
      detail: peerReady ? `${signal.compareCount} funds in context.` : "Keep the shortlist small.",
      ready: peerReady
    },
    {
      label: "Write",
      title: memoReady ? "Reason captured" : "Reason not written",
      detail: memoReady ? "Memo can move to review." : "Write one plain-English reason.",
      ready: memoReady
    }
  ];
  const nextStep = steps.find((step) => !step.ready) || {
    label: "Review",
    title: "Save review rhythm",
    detail: "Keep the next check visible.",
    ready: reviewReady
  };
  return {
    label: "Quiet decision rail",
    headline: "One decision, three calm checks.",
    cue: `Current room: ${routeLabel}. The desk advances only when the next check is clear.`,
    nextLabel: nextStep.label,
    nextTitle: nextStep.title,
    nextDetail: nextStep.detail,
    steps
  };
}

function serenityStartSurface(signal, journey, readiness, nextCue) {
  const blocked = readiness.status !== "Memo-ready";
  const question = journey?.question?.label || "What proof is missing?";
  const detail = blocked
    ? "Keep the decision quiet until evidence, peer, and memo checks are visible."
    : "The research can move to a written memo, but it is still not an execution instruction.";
  const rule = "One fund. One fair peer. One written reason.";
  const boundary = signal.evidence < 78
    ? "Do not judge before source dates."
    : signal.compareCount < 2
      ? "Do not judge before one fair peer."
      : readiness.status === "Memo-ready"
        ? "Write before any action."
        : "Pause before money moves.";
  return {
    label: "One calm start",
    question,
    detail,
    rule,
    context: "Search first. Filters can wait.",
    plainStart: "Begin with one name, then let the desk slow the decision down.",
    actionPath: ["Pause", "Verify", "Write"],
    commitment: {
      label: "Tiny commitment",
      text: "Give this fund three quiet minutes before any conclusion.",
      proof: "One source, one peer, one written line."
    },
    shortlistBoundary: {
      label: "Shortlist boundary",
      text: `${signal.fund.name} is being checked for shortlist fit, not chosen today.`
    },
    decisionRail: quietDecisionRail(signal, readiness, journey),
    conviction: quietConvictionMeter(readiness),
    privacyLedger: privacyLearningLedger(signal, readiness, journey),
    compass: calmReviewCompass(signal, readiness, journey),
    learningContract: learningFlywheelContract(signal, readiness, journey),
    learningReceipt: calmLearningReceipt(signal, readiness, journey),
    improvementPromise: calmImprovementPromise(signal, readiness, journey),
    evidenceBeacon: calmEvidenceBeacon(signal, readiness, journey),
    learningLoop: learningLoopLedger(signal, readiness),
    federatedLoop: federatedTrustLoop(signal, readiness),
    learningConsent: learningConsentGate(signal, readiness),
    outcomeLearning: outcomeLearningSignal(signal, readiness),
    promises: ["Research only", "No rush", "No personal IDs"],
    boundary,
    button: nextCue.button,
    route: nextCue.route
  };
}

