function makeEntitlementBridgeBrief() {
  const bridge = entitlementBridgeConfig();
  return [
    "# NiveshNadi Entitlement Bridge",
    `Release: ${RELEASE_LABEL} (${DATA_VERSION})`,
    `Score: ${bridge.score}/100`,
    `Status: ${bridge.status}`,
    `Plan: ${entitlementBridgePlanLabel(bridge.plan)} | ${bridge.planMeta.price} ${bridge.planMeta.cadence}`,
    `Lifecycle: ${entitlementBridgeLifecycleLabel(bridge.lifecycle)}`,
    `Policy: ${entitlementBridgePolicyLabel(bridge.policy)}`,
    `Receipt: ${entitlementBridgeReceiptLabel(bridge.receipt)}`,
    "",
    "## Feature Access",
    ...bridge.featureAccess.map((feature) => `- ${feature.label}: ${feature.access} | ${feature.detail}`),
    "",
    "## Access Matrix",
    ...bridge.accessMatrix.map((item) => `- ${item.label}: ${item.decision} | ${item.lifecycleImpact} | receipt gate: ${item.receiptGate}`),
    "",
    "## Receipt Replay Proof",
    ...bridge.replayProofs.map((proof) => `- ${proof.label}: ${proof.status} | ${proof.effect}`),
    "",
    "## Entitlement Route",
    ...bridge.lifecycleRoute.map((item) => `- ${item}`),
    "",
    "## Entitlement States",
    ...ENTITLEMENT_BRIDGE_STATES.map((state) => `- ${state.label}: ${state.score}/100 | ${state.event} | ${state.guardrail}`),
    "",
    "## Blockers",
    ...(bridge.blockers.length ? bridge.blockers.map((item) => `- ${item}`) : ["- No active entitlement blocker in this preview."]),
    "",
    "## Guardrail",
    "Entitlement Bridge is launch planning only. Real paid access must be driven by backend-verified payment events, account ownership, export/delete controls, and redacted support receipts. It must not store card, UPI, bank, PAN, folio, CAS, ARN, EUIN, or distributor client data."
  ].join("\n");
}

function openEntitlementBlocker() {
  const bridge = entitlementBridgeConfig();
  scrollToHash(bridge.blockers.length ? "#backend-audit-receipts" : "#account-launch", "smooth", true);
}

function subscriptionOpsQueueLabel(queue) {
  return {
    renewal: "Renewal operations",
    failed: "Failed payment triage",
    refund: "Refund and cancellation desk",
    invoice: "Invoice and tax review",
    reconcile: "Settlement reconciliation",
    support: "Support repair queue"
  }[queue] || "Renewal operations";
}

function subscriptionOpsRiskLabel(risk) {
  return {
    normal: "Normal beta traffic",
    attention: "Attention needed",
    critical: "Critical launch risk",
    freeze: "Launch freeze"
  }[risk] || "Normal beta traffic";
}

function subscriptionOpsRunbookLabel(runbook) {
  return {
    auto: "Automated ops runbook",
    review: "Ops review required",
    manual: "Manual founder support",
    missing: "No runbook"
  }[runbook] || "Ops review required";
}

function subscriptionOpsReceiptLabel(receipt) {
  return {
    eventStream: "Event stream receipts",
    auditReady: "Backend audit receipts",
    spreadsheet: "Manual spreadsheet tracker",
    missing: "No receipt trail"
  }[receipt] || "Backend audit receipts";
}

function subscriptionOpsConfig() {
  const queue = els.subscriptionOpsQueue?.value || "renewal";
  const risk = els.subscriptionOpsRisk?.value || "attention";
  const runbook = els.subscriptionOpsRunbook?.value || "review";
  const receipt = els.subscriptionOpsReceipt?.value || "auditReady";
  const base = Math.round(SUBSCRIPTION_OPS_STATES.reduce((sum, state) => sum + state.score, 0) / SUBSCRIPTION_OPS_STATES.length);
  const queueDelta = {
    renewal: 8,
    failed: 2,
    refund: 0,
    invoice: -2,
    reconcile: 4,
    support: 0
  }[queue] || 0;
  const riskDelta = risk === "normal" ? 12 : risk === "attention" ? 4 : risk === "critical" ? -10 : -24;
  const runbookDelta = runbook === "auto" ? 12 : runbook === "review" ? 6 : runbook === "manual" ? -8 : -26;
  const receiptDelta = receipt === "auditReady" ? 14 : receipt === "eventStream" ? 10 : receipt === "spreadsheet" ? -14 : -28;
  const score = clampNumber(base + queueDelta + riskDelta + runbookDelta + receiptDelta, 16, 94);
  const opsRoute = {
    renewal: ["renewal job queued", "gateway attempt checked", "entitlement refreshed", "invoice status verified", "next renewal scheduled"],
    failed: ["payment failure received", "user notice issued", "grace applied", "retry scheduled", "support route opened"],
    refund: ["refund request checked", "gateway refund submitted", "entitlement downgraded", "invoice adjusted", "support receipt closed"],
    invoice: ["invoice status pulled", "tax posture checked", "receipt URL verified", "user copy prepared", "finance exception routed"],
    reconcile: ["settlement file imported", "gateway total compared", "app entitlement count checked", "variance routed", "month closed"],
    support: ["support case opened", "redacted account state checked", "entitlement repair reviewed", "user notice drafted", "case closed"]
  }[queue] || ["renewal job queued", "gateway attempt checked", "entitlement refreshed", "invoice status verified", "next renewal scheduled"];
  const blockers = [
    ...(risk === "critical" ? ["critical launch risk needs owner, rollback path, and user notice before continuing"] : []),
    ...(risk === "freeze" ? ["launch freeze should stop paid rollout until incident and entitlement state are repaired"] : []),
    ...(runbook === "missing" ? ["ops runbook is missing, so support cannot safely handle subscription events"] : []),
    ...(runbook === "manual" ? ["manual founder support cannot scale to public paid launch"] : []),
    ...(receipt === "spreadsheet" ? ["manual spreadsheet tracker is not enough for subscription audit and reconciliation"] : []),
    ...(receipt === "missing" ? ["missing receipt trail makes entitlement, refund, and invoice state untrustworthy"] : []),
    ...(queue === "invoice" ? ["invoice and GST posture need finance/legal signoff before paid launch"] : []),
    ...(queue === "refund" ? ["refund path needs clear entitlement downgrade and user-visible policy"] : [])
  ];
  const status = score >= 82 && !blockers.length
    ? "Ops beta ready"
    : score >= 58
      ? "Ops dry-run"
      : "Launch blocker";
  const tone = status === "Ops beta ready" ? "ready" : status === "Launch blocker" ? "blocked" : "draft";
  const metrics = [
    {
      label: "Queue",
      score: queue === "renewal" ? 74 : queue === "reconcile" ? 70 : queue === "failed" ? 62 : queue === "support" ? 58 : 54,
      detail: subscriptionOpsQueueLabel(queue)
    },
    {
      label: "Risk",
      score: risk === "normal" ? 82 : risk === "attention" ? 66 : risk === "critical" ? 34 : 18,
      detail: subscriptionOpsRiskLabel(risk)
    },
    {
      label: "Runbook",
      score: runbook === "auto" ? 84 : runbook === "review" ? 72 : runbook === "manual" ? 44 : 16,
      detail: subscriptionOpsRunbookLabel(runbook)
    },
    {
      label: "Receipt",
      score: receipt === "auditReady" ? 86 : receipt === "eventStream" ? 78 : receipt === "spreadsheet" ? 36 : 12,
      detail: subscriptionOpsReceiptLabel(receipt)
    }
  ];
  const opsLanes = [
    {
      label: "User notice",
      state: risk === "normal" ? "Standard copy" : "Clear intervention copy",
      detail: "Explain renewal, grace, refund, or expiry without nudging transactions."
    },
    {
      label: "Support view",
      state: runbook === "manual" ? "Reviewer required" : "Redacted lookup",
      detail: "Support sees plan, state, receipt, and limits, not PAN, folio, CAS, bank, or private notes."
    },
    {
      label: "Finance check",
      state: queue === "reconcile" || queue === "invoice" ? "Primary lane" : "Linked receipt",
      detail: "Invoice, refund, and settlement state should agree with entitlement state."
    },
    {
      label: "Rollback",
      state: risk === "freeze" ? "Immediate freeze" : "Prepared",
      detail: "Ops can pause paid feature changes and preserve a clean audit trail."
    }
  ];
  return {
    blockers,
    metrics,
    opsLanes,
    opsRoute,
    queue,
    receipt,
    risk,
    runbook,
    score,
    status,
    tone
  };
}

function productionSupportTooling(ops) {
  const redactedLookupScore = ops.receipt === "missing" ? 24 : ops.receipt === "spreadsheet" ? 38 : 74;
  const caseRouterScore = ops.runbook === "missing" ? 18 : ops.runbook === "manual" ? 42 : ops.runbook === "auto" ? 82 : 70;
  const entitlementRepairScore = ops.queue === "support" || ops.queue === "failed" || ops.queue === "refund" ? 68 : 58;
  const billingEvidenceScore = ops.queue === "invoice" || ops.queue === "reconcile" || ops.queue === "refund" ? 70 : 56;
  const incidentDeskScore = ops.risk === "freeze" ? 34 : ops.risk === "critical" ? 48 : ops.risk === "attention" ? 62 : 78;
  const ownerScore = ops.risk === "normal" && ops.runbook !== "missing" ? 76 : ops.runbook === "missing" ? 26 : 60;
  const blockers = [
    ...ops.blockers,
    ...(ops.receipt === "missing" ? ["support tooling cannot open without receipt-backed case history"] : []),
    ...(ops.receipt === "spreadsheet" ? ["spreadsheet tracker cannot be the production support source of truth"] : []),
    ...(ops.runbook === "missing" ? ["support team needs selected runbook, owner, escalation path, and closeout rules"] : []),
    ...(ops.runbook === "manual" ? ["manual founder support must be replaced by a controlled support view before public launch"] : []),
    ...(ops.risk === "freeze" ? ["launch freeze requires support queue pause, user notice, rollback owner, and incident closeout"] : [])
  ];
  const readiness = clampNumber(Math.round((
    redactedLookupScore +
    caseRouterScore +
    entitlementRepairScore +
    billingEvidenceScore +
    incidentDeskScore +
    ownerScore
  ) / 6) - blockers.length * 3, 16, 92);
  const status = blockers.length
    ? "Support tooling blocked"
    : readiness >= 72
      ? "Support tooling ready"
      : "Support tooling dry-run";
  const tone = blockers.length
    ? "blocked"
    : readiness >= 72
      ? "ready"
      : "draft";
  const receiptId = [
    "NN",
    "SUPPORT",
    "TOOLING",
    DATA_VERSION.replace(/-/g, ""),
    ops.queue,
    ops.receipt
  ].join("-").toUpperCase();
  const metrics = [
    {
      label: "Tooling posture",
      value: status,
      detail: blockers[0] || "Renewal, billing, entitlement repair, and incident support can move into a controlled support dry-run."
    },
    {
      label: "Support receipt",
      value: receiptId,
      detail: "One receipt family should bind case open, redacted lookup, action, escalation, user notice, and closeout."
    },
    {
      label: "Support surface",
      value: subscriptionOpsQueueLabel(ops.queue),
      detail: "The active queue determines the first support script and evidence checklist."
    },
    {
      label: "Exposure rule",
      value: "Redacted only",
      detail: "Support can see subscription state, receipts, and action history, not payment instruments or private research notes."
    }
  ];
  const tools = [
    {
      label: "Redacted lookup",
      owner: "Support",
      score: redactedLookupScore,
      proof: "user hash, plan state, receipt ids, support-safe event history",
      action: "Open only the minimum fields needed to solve billing or access cases."
    },
    {
      label: "Case router",
      owner: "Ops Lead",
      score: caseRouterScore,
      proof: "case category, severity, owner, due time, escalation path",
      action: "Route failed payment, refund, invoice, entitlement, reconciliation, and incident cases to the correct owner."
    },
    {
      label: "Entitlement repair",
      owner: "Account Ops",
      score: entitlementRepairScore,
      proof: "prior state, proposed state, source receipt, reviewer role",
      action: "Repair access through a reversible backend event, not direct browser edits."
    },
    {
      label: "Billing evidence",
      owner: "Finance",
      score: billingEvidenceScore,
      proof: "invoice id, refund id, settlement id, variance state",
      action: "Finance answers billing questions from receipt references and settlement evidence."
    },
    {
      label: "Incident desk",
      owner: "Ops Lead",
      score: incidentDeskScore,
      proof: "incident id, affected receipts, user notice, rollback state",
      action: "Freeze, replay, repair, notify, and close incidents before the cohort widens."
    },
    {
      label: "Closeout owner",
      owner: "Founder",
      score: ownerScore,
      proof: "case result, user notice, audit note, next prevention step",
      action: "Every support case needs a closeout reason and product-learning route."
    }
  ];
  const scripts = [
    "Open case with category, severity, receipt family, and no private investment identifiers.",
    "Check redacted subscription state, payment event posture, entitlement state, and prior support actions.",
    "Choose action: user notice, entitlement repair, refund route, invoice check, reconciliation route, or incident freeze.",
    "Record support receipt with actor role, source receipt, user-safe notice, status, and closeout owner.",
    "Escalate repeated cases into product, finance, backend, privacy, or compliance fixes before widening beta."
  ];
  const guardrails = [
    "Support must not see PAN, folio, CAS, bank, UPI, card, OTP, gateway secrets, ARN/EUIN, or private research notes.",
    "Support can explain account access and billing state, not provide investment advice or transaction guidance.",
    "Manual repairs must be rare, reversible, receipt-bound, and reviewed before production launch.",
    "Phase 2 distributor support needs separate consent, roles, client-data separation, and regulatory review."
  ];
  return {
    blockers: blockers.length ? blockers : ["No active support tooling blocker in this preview. Keep tooling in dry-run until backend receipt contracts are implemented."],
    guardrails,
    metrics,
    readiness,
    receiptId,
    scripts,
    status,
    tone,
    tools
  };
}

